int licznik = 0;
int liczba = 0;

int minimum, maksimum, jasnosc;

// Funkcja wyswietlania cyfr na wyswietlaczu
void Znak(int iNumer) {

  switch (iNumer) {

    case 0:
      PORTD = (PORTD & 0b00000011) | 0b00000000;
      PORTB |= 0b00000001;
      break;

    case 1:
      PORTD = (PORTD & 0b00000011) | 0b11100100;
      PORTB |= 0b00000001;
      break;

    case 2:
      PORTD = (PORTD & 0b00000011) | 0b10010000;
      PORTB &= 0b11111110;
      break;

    case 3:
      PORTD = (PORTD & 0b00000011) | 0b11000000;
      PORTB &= 0b11111110;
      break;

    case 4:
      PORTD = (PORTD & 0b00000011) | 0b01100100;
      PORTB &= 0b11111110;
      break;

    case 5:
      PORTD = (PORTD & 0b00000011) | 0b01001000;
      PORTB &= 0b11111110;
      break;

    case 6:
      PORTD = (PORTD & 0b00000011) | 0b00001000;
      PORTB &= 0b11111110;
      break;

    case 7:
      PORTD = (PORTD & 0b00000011) | 0b11100000;
      PORTB |= 0b00000001;
      break;

    case 8:
      PORTD = (PORTD & 0b00000011) | 0b00000000;
      PORTB &= 0b11111110;
      break;

    case 9:
      PORTD = (PORTD & 0b00000011) | 0b01000000;
      PORTB &= 0b11111110;
      break;

    default:
      PORTD = (PORTD & 0b00000011) | 0b11011000;
      PORTB &= 0b11111110;
      break;
  }
}

void setup() {

  // D2-D7 jako wyjscia
  DDRD |= 0b11111100;

  // D8, D10 i D11 jako wyjscia
  DDRB |= 0b00001101;

  // Wylaczenie obu wyswietlaczy
  PORTB &= 0b11110011;

  delay(1000);

  // Inicjalizacja zakresu pomiarowego
  minimum = analogRead(A0);
  maksimum = minimum;
}

void loop() {

  // Wylaczenie drugiego wyswietlacza
  PORTB &= 0b11110111;

  // Wyswietlenie jednosci
  Znak(liczba % 10);

  // Wlaczenie pierwszego wyswietlacza (D10)
  PORTB |= 0b00000100;

  delay(2);

  // Wylaczenie pierwszego wyswietlacza
  PORTB &= 0b11111011;

  // Wyswietlenie dziesiatek
  Znak((liczba / 10) % 10);

  // Wlaczenie drugiego wyswietlacza (D11)
  PORTB |= 0b00001000;

  delay(2);

  // Odczyt jasnosci co pewien czas
  if (licznik++ > 100) {

    jasnosc = analogRead(A0);

    if (minimum > jasnosc) {
      minimum = jasnosc;
    }

    if (maksimum < jasnosc) {
      maksimum = jasnosc;
    }

    // Przeliczenie jasnosci na zakres 0-99
    if (minimum != maksimum) {
      jasnosc = 99L * (jasnosc - minimum) /
                (maksimum - minimum);
    }
    else {
      jasnosc = 0;
    }

    liczba = constrain(jasnosc, 0, 99);

    licznik = 0;
  }
}
